const r = await tools.exec_command({cmd:"python3 - <<'PY'
from pathlib import Path
for p in sorted(Path('src/handlers').rglob('*')):
    if not p.is_file():
        continue
    data = p.read_bytes()
    old = b'TIMEOUT_MS = 3000'
    if old not in data:
        continue
    try:
        with p.open('r+b') as f:
            f.write(data.replace(old, b'TIMEOUT_MS = 5000'))
        print('UPDATED:', p)
    except OSError as e:
        print('DENIED:', p, str(e))
PY","max_output_tokens":2000}); text(r.output);

